const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const event = String(body.event || body.type || 'unknown.created');
const timestamp = String(headers['x-twenty-webhook-timestamp'] || headers['X-Twenty-Webhook-Timestamp'] || '');
const signature = String(headers['x-twenty-webhook-signature'] || headers['X-Twenty-Webhook-Signature'] || '');
const secret = String($env.TWENTY_INBOUND_WEBHOOK_SECRET || '');
const payloadString = JSON.stringify(body || {});
let signatureValid = true;
let stale = false;
let signatureReason = 'not_required';

if (secret) {
  const hasHeaders = Boolean(timestamp && signature);
  signatureValid = hasHeaders;
  signatureReason = hasHeaders ? 'header_present_hmac_check_delegated' : 'missing_signature_headers';
}

if (timestamp) {
  const tsMs = Date.parse(timestamp);
  if (!Number.isNaN(tsMs)) {
    stale = Math.abs(Date.now() - tsMs) > 10 * 60 * 1000;
  }
}

const record = body.record || body.data || {};
const objectType = event.includes('.') ? event.split('.')[0] : (record.objectType || record.type || 'unknown');
const action = event.includes('.') ? event.split('.')[1] : 'updated';
const supportedWakeEvents = new Set([
  'person.created','person.updated','person.deleted',
  'company.created','company.updated','company.deleted',
  'opportunity.created','opportunity.updated','opportunity.deleted',
  'note.created','note.updated','note.deleted',
  'task.created','task.updated','task.deleted',
  'message.created','message.updated','message.deleted',
  'activity.created','activity.updated','activity.deleted'
]);
const isProspectingObject = ['prospectsignal','sequenceenrollment','enrichmentjob','researchsnapshot'].includes(String(objectType).toLowerCase());
const highValueFieldHints = ['owner','status','stage','lead','score','nextStep','closeDate','amount','companyId','personId'];
const changedFields = Array.isArray(body.changedFields) ? body.changedFields : (Array.isArray(record.changedFields) ? record.changedFields : []);
const highValueChange = changedFields.some((f) => highValueFieldHints.some((hint) => String(f).toLowerCase().includes(hint.toLowerCase())));

const eventId = String(body.id || body.eventId || record.id || `${event}:${timestamp}`);
const dedupeKey = `${event}:${eventId}:${timestamp}`;
const g = $getWorkflowStaticData('global');
g.twentyInboundSeen = g.twentyInboundSeen || {};
const now = Date.now();
for (const [k, v] of Object.entries(g.twentyInboundSeen)) {
  if (typeof v === 'number' && now - v > 24 * 60 * 60 * 1000) delete g.twentyInboundSeen[k];
}
const duplicate = Boolean(g.twentyInboundSeen[dedupeKey]);
if (!duplicate) g.twentyInboundSeen[dedupeKey] = now;

const firstName = record?.name?.firstName || record?.firstName || '';
const lastName = record?.name?.lastName || record?.lastName || '';
const contactName = `${firstName} ${lastName}`.trim() || record?.name || '';
const email = record?.emails?.primaryEmail || record?.email || record?.primaryEmail || '';
const phone = record?.phones?.primaryPhoneNumber || record?.phone || record?.mobile || '';
const company = record?.company?.name || record?.company || record?.companyName || '';
const notes = record?.notes || record?.description || '';

const shouldWakeByEvent = supportedWakeEvents.has(event);
const shouldWake = signatureValid && !stale && !duplicate && (shouldWakeByEvent || isProspectingObject || highValueChange);
const syncDirection = 'twenty_to_n8n';

return [{
  json: {
    channel: 'twenty-webhook',
    conversation_id: String(record?.id || body?.id || `twenty:${Date.now()}`),
    user_id: String(email || phone || record?.id || ''),
    message: `Evento Twenty (${event}). Contacto: ${contactName || 'sin nombre'}. Empresa: ${company || 'sin empresa'}. Notas: ${notes || 'sin notas'}`,
    attachments: [],
    metadata: {
      twenty_event: event,
      twenty_record_id: record?.id || null,
      contact_name: contactName,
      email,
      phone,
      company,
      changed_fields: changedFields,
      source_system: 'twenty',
      source_event_id: eventId,
      correlation_id: String(body.correlationId || body.traceId || eventId),
      idempotency_key: dedupeKey,
      actor_type: String(body.actorType || record.actorType || 'unknown'),
      sync_direction: syncDirection,
      sync_status: shouldWake ? 'sync.requested' : (duplicate ? 'sync.skipped_no_change' : 'agent.needs_human_review'),
      last_sync_error: signatureValid ? '' : signatureReason,
      wake_agent: shouldWake,
      duplicate,
      stale,
      signature_valid: signatureValid,
      signature_reason: signatureReason,
      raw_payload: body
    }
  }
}];
